CREATE TABLE "execucao_pedido" (
	"id" uuid PRIMARY KEY NOT NULL,
	"execucao_id" uuid NOT NULL,
	"tipo" text NOT NULL,
	"solicitante_id" uuid NOT NULL,
	"instante" timestamp with time zone NOT NULL,
	"motivo" text,
	"complemento" text,
	"latitude" numeric(9, 6),
	"longitude" numeric(9, 6),
	"criado_em" timestamp with time zone NOT NULL,
	"expira_em" timestamp with time zone NOT NULL,
	"estado" text DEFAULT 'aberto' NOT NULL,
	"decidido_por" uuid,
	"decidido_em" timestamp with time zone,
	"motivo_recusa" text,
	CONSTRAINT "execucao_pedido_tipo_check" CHECK ("execucao_pedido"."tipo" in ('encerrar', 'suspender')),
	CONSTRAINT "execucao_pedido_estado_check" CHECK ("execucao_pedido"."estado" in ('aberto', 'aprovado', 'aprovado_por_prazo', 'recusado', 'cancelado', 'obsoleto')),
	CONSTRAINT "execucao_pedido_gps_completo" CHECK (("execucao_pedido"."latitude" is null) = ("execucao_pedido"."longitude" is null)),
	CONSTRAINT "execucao_pedido_prazo" CHECK ("execucao_pedido"."expira_em" > "execucao_pedido"."criado_em"),
	CONSTRAINT "execucao_pedido_decisao" CHECK (("execucao_pedido"."estado" = 'aberto') = ("execucao_pedido"."decidido_em" is null) and ("execucao_pedido"."estado" in ('aprovado', 'recusado')) = ("execucao_pedido"."decidido_por" is not null)),
	CONSTRAINT "execucao_pedido_suspensao_com_motivo" CHECK ("execucao_pedido"."tipo" <> 'suspender' or "execucao_pedido"."motivo" is not null)
);
--> statement-breakpoint
